INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('which permits expire in the next hour?')||':permit-issuer:aramco'),'Which permits expire in the next hour?','permit-issuer','aramco','Table','SELECT p.id,p.permit_type,p.valid_to,p.issuer,z.name AS zone_name,EXTRACT(EPOCH FROM (p.valid_to-NOW()))/60 AS minutes_remaining FROM permit p JOIN zone z ON z.id=p.zone_id WHERE p.status=''''valid'''' AND p.valid_to<=NOW()+INTERVAL''''1 hour'''' ORDER BY p.valid_to ASC','Table',FALSE,NULL,'["Issue an extension with fresh conditions", "Show me the general permit in the confined-space zone", "Where is my issue-to-verify time going?"]'::jsonb,'Anomaly Detection',NULL,NOW(),0);
