INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('where is my issue-to-verify time going?')||':permit-issuer:aramco'),'Where is my issue-to-verify time going?','permit-issuer','aramco','Table','SELECT p.permit_type,COUNT(*) AS total,AVG(EXTRACT(EPOCH FROM (NOW()-p.valid_from))/60) AS avg_minutes_since_issued,COUNT(CASE WHEN p.status=''''pending_verification'''' THEN 1 END) AS pending FROM permit p WHERE p.valid_from>=NOW()-INTERVAL''''24 hours'''' GROUP BY p.permit_type ORDER BY avg_minutes_since_issued DESC','Table',FALSE,NULL,'["Which permits expire in the next hour?", "Why did the night shift not log an extension?", "Show me the permits that lapsed with workers still on location"]'::jsonb,'Converged Conversation',NULL,NOW(),0);
