INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('show me safety exposure by unit')||':complex-manager:aramco'),'Show me safety exposure by unit','complex-manager','aramco','Table','SELECT z.id,z.name,z.hazard_level,COUNT(DISTINCT w.id) AS workers,COUNT(DISTINCT p.id) AS active_permits,COUNT(DISTINCT CASE WHEN p.risk_bucket IN (''''safety'''',''''health'''') THEN p.id END) AS high_risk_permits,COUNT(DISTINCT fj.id) AS flagged_jobs FROM zone z LEFT JOIN worker w ON w.zone_id=z.id LEFT JOIN permit p ON p.zone_id=z.id AND p.status=''''valid'''' LEFT JOIN flagged_job fj ON fj.zone_id=z.id GROUP BY z.id,z.name,z.hazard_level ORDER BY flagged_jobs DESC,high_risk_permits DESC','Table',FALSE,NULL,'["What is the schedule versus safety trade-off?", "Why are the headcounts disagreeing?", "What would I tell the board''s safety committee today?"]'::jsonb,'Proactive Intelligence',NULL,NOW(),0);
INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('what is the schedule versus safety trade-off?')||':complex-manager:aramco'),'What is the schedule versus safety trade-off?','complex-manager','aramco','Table','SELECT z.name AS zone_name,z.hazard_level,COUNT(DISTINCT fj.id) AS flagged_violations,COUNT(DISTINCT p.id) AS active_permits,COUNT(DISTINCT CASE WHEN p.status=''''expired'''' THEN p.id END) AS expired_permits,COUNT(DISTINCT w.id) AS workers_on_site FROM zone z LEFT JOIN flagged_job fj ON fj.zone_id=z.id LEFT JOIN permit p ON p.zone_id=z.id LEFT JOIN worker w ON w.zone_id=z.id WHERE z.hazard_level=''''high'''' GROUP BY z.id,z.name,z.hazard_level ORDER BY flagged_violations DESC','Table',FALSE,NULL,'["Show me safety exposure by unit", "What happens at the next surge?", "What would I tell the board''s safety committee today?"]'::jsonb,'Converged Conversation',NULL,NOW(),0);
INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('why are the headcounts disagreeing?')||':complex-manager:aramco'),'Why are the headcounts disagreeing?','complex-manager','aramco','HeadcountReconciliationPanel','SELECT rr.as_of,rr.resolved_count,rr.method,rs.source_name,rs.record_count,rs.delta,rs.reliability,rs.note FROM reconciliation_run rr JOIN reconciliation_source rs ON rs.reconciliation_id=rr.id ORDER BY rr.as_of DESC,ABS(rs.delta) DESC','ReconciliationPanel',TRUE,'get_reconciliation','["What would I tell the board''s safety committee today?", "Show me safety exposure by unit", "What happens at the next surge?"]'::jsonb,'Converged Conversation',NULL,NOW(),0);
INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('what happens at the next surge?')||':complex-manager:aramco'),'What happens at the next surge?','complex-manager','aramco','Table','SELECT z.name AS zone_name,z.hazard_level,z.occupancy_capacity,COUNT(DISTINCT w.id) AS current_workers,z.occupancy_capacity-COUNT(DISTINCT w.id) AS remaining_capacity,COUNT(DISTINCT p.id) AS active_permits FROM zone z LEFT JOIN worker w ON w.zone_id=z.id LEFT JOIN permit p ON p.zone_id=z.id AND p.status=''''valid'''' GROUP BY z.id,z.name,z.hazard_level,z.occupancy_capacity ORDER BY remaining_capacity ASC','Table',FALSE,NULL,'["What is the schedule versus safety trade-off?", "What would I tell the board''s safety committee today?", "Show me safety exposure by unit"]'::jsonb,'Converged Conversation',NULL,NOW(),0);
INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('what would i tell the board''s safety committee today?')||':complex-manager:aramco'),'What would I tell the board''s safety committee today?','complex-manager','aramco','Table','SELECT metric,value FROM (SELECT 1 AS ord,''''Active Permits'''' AS metric,COUNT(*)::text AS value FROM permit WHERE status=''''valid'''' UNION ALL SELECT 2,''''High Risk Permits'''',COUNT(*)::text FROM permit WHERE status=''''valid'''' AND risk_bucket IN (''''safety'''',''''health'''') UNION ALL SELECT 3,''''Flagged Violations'''',COUNT(*)::text FROM flagged_job UNION ALL SELECT 4,''''People On Site'''',COUNT(*)::text FROM worker UNION ALL SELECT 5,''''Overdue Actions'''',COUNT(*)::text FROM action WHERE status!=''''done'''' UNION ALL SELECT 6,''''Muster Completion'''',(SELECT measured_completion_label FROM muster_event ORDER BY as_of DESC LIMIT 1)) summary ORDER BY ord','Table',FALSE,NULL,'["Assemble the committee pack", "Why are the headcounts disagreeing?", "What happens at the next surge?"]'::jsonb,'Converged Conversation',NULL,NOW(),0);
INSERT INTO query_cache (question_hash,question,persona_id,client_id,component,sql_query,viz_type,is_known_component,query_fn,suggested_chips,capability,ai_message,cached_at,hit_count) VALUES (md5(lower('assemble the committee pack')||':complex-manager:aramco'),'Assemble the committee pack','complex-manager','aramco','Table','SELECT z.name AS zone,z.hazard_level,COUNT(DISTINCT fj.id) AS violations,COUNT(DISTINCT p.id) AS permits,COUNT(DISTINCT w.id) AS workers,rr.resolved_count AS reconciled_headcount FROM zone z LEFT JOIN flagged_job fj ON fj.zone_id=z.id LEFT JOIN permit p ON p.zone_id=z.id AND p.status=''''valid'''' LEFT JOIN worker w ON w.zone_id=z.id CROSS JOIN (SELECT resolved_count FROM reconciliation_run ORDER BY as_of DESC LIMIT 1) rr GROUP BY z.id,z.name,z.hazard_level,rr.resolved_count ORDER BY violations DESC','Table',FALSE,NULL,'["What would I tell the board''s safety committee today?", "Show me safety exposure by unit", "Why are the headcounts disagreeing?"]'::jsonb,'Automated Action',NULL,NOW(),0);